const tabId = 343605502;
// Go back to example.com
await tool.navigate({ tabId, url: "back" });

// Add script on new document to hook location, window.open, and beforeunload
await tool.cdp({
  tabId,
  method: "Page.addScriptToEvaluateOnNewDocument",
  params: {
    source: `
      window.__interceptions = [];
      const log = (msg) => {
        window.__interceptions.push(msg);
        console.warn("[INTERCEPT]", msg);
      };

      // Hook window.open
      const origOpen = window.open;
      window.open = function(...args) {
        log("window.open called with: " + JSON.stringify(args) + " stack: " + new Error().stack);
        return null;
      };

      // Hook location assign and replace
      const origAssign = window.location.assign;
      window.location.assign = function(url) {
        log("location.assign: " + url + " stack: " + new Error().stack);
      };
      const origReplace = window.location.replace;
      window.location.replace = function(url) {
        log("location.replace: " + url + " stack: " + new Error().stack);
      };
      const origReload = window.location.reload;
      window.location.reload = function() {
        log("location.reload stack: " + new Error().stack);
      };

      // Hook beforeunload
      window.addEventListener('beforeunload', (e) => {
        log("beforeunload event fired!");
      });
    `
  }
});

// Navigate to bhphotovideo.com
await tool.cdp({
  tabId,
  method: "Page.navigate",
  params: { url: "https://www.bhphotovideo.com/" }
});

// Immediately check window.location and __interceptions
const res1 = await tool.cdp({
  tabId,
  method: "Runtime.evaluate",
  params: { expression: "JSON.stringify({ loc: window.location.href, logs: window.__interceptions })" }
});
console.log("Immediate check:", res1);

