};

const res = await tool.fetch_url({
  url: "https://www.bhphotovideo.com/c/browse/Computers-Accessories/ci/15241/N/4294210528",
  headers
});

console.log("Status:", res.status);
console.log("Length:", res.body?.length);

// Let's parse ServerStateStore data to see the subcategories
const m = res.body?.match(/data-data="([^"]+)"/);
if (m) {
  const jsonStr = m[1].replace(/&quot;/g, '"');
  const data = JSON.parse(jsonStr);
  console.log("Stores:", Object.keys(data));
  const serverEntries = data.ServerStateStore?.state?.entries;
  if (serverEntries) {
    for (const [k, v] of Object.entries(serverEntries)) {
      console.log("Key:", k, "Query:", v.query?.url);
      if (v.data?.categoryGroups) {
        for (const cg of v.data.categoryGroups) {
          console.log("Group:", cg.name);
          for (const c of cg.categories) {
            console.log(" - Category:", c.name, c.url);
          }
        }
      }
    }
  }
}

