const headers = {
  "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36",
  "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8",
  "Accept-Language": "en-US,en;q=0.9"
};

const res = await tool.fetch_url({
  url: "https://www.bhphotovideo.com/a/cart",
  headers
});

const m = res.body?.match(/data-data="([^"]+)"/);
if (m) {
  const jsonStr = m[1].replace(/&quot;/g, '"');
  const data = JSON.parse(jsonStr);
  console.log("Cart stores:", Object.keys(data));
  const serverEntries = data.ServerStateStore?.state?.entries || {};
  for (const [k, v] of Object.entries(serverEntries)) {
    console.log("Server entry:", v.query?.url);
    if (v.data?.cart || v.data?.items) {
      console.log("Cart data:", JSON.stringify(v.data).slice(0, 1000));
    }
  }
  if (data.CartStore) {
    console.log("CartStore:", JSON.stringify(data.CartStore).slice(0, 1000));
  }
}

// Check for 1884010 or Mac Studio or price
console.log("Contains 1884010:", res.body?.includes("1884010"));
console.log("Contains Mac Studio:", res.body?.includes("Mac Studio"));
console.log("Contains 6,899:", res.body?.includes("6,899") || res.body?.includes("6899"));

