  headers
});

const html = res.body;

// Search for script chunks mentioned in product HTML
const chunks = [];
for (const m of html.matchAll(/src="([^"]*\.js)"/gi)) {
  chunks.push(m[1]);
}
console.log("Chunks:", chunks);

